const listVariantsOfProducts = `-- name: ListVariantsOfProducts :many
SELECT v.id, v.product_id, v.sku, v.ean, v.option_values, v.price_cents, v.compare_at_cents,
       s.sku AS supplier_sku, s.source_id, s.cost_cents, s.rrp_cents, s.availability_status
FROM variant v
LEFT JOIN variant_supplier_item vs ON vs.variant_id = v.id AND vs.preferred
LEFT JOIN supplier_item s ON s.id = vs.supplier_item_id
WHERE v.product_id = ANY($1::bigint[])
ORDER BY v.product_id, v.option_values::text, v.sku
`

type ListVariantsOfProductsRow struct {
	ID                 int64
	ProductID          int64
	Sku                string
	Ean                string
	OptionValues       []byte
	PriceCents         *int64
	CompareAtCents     *int64
	SupplierSku        *string
	SourceID           *string
	CostCents          *int64
	RrpCents           *int64
	AvailabilityStatus *string
}

func (q *Queries) ListVariantsOfProducts(ctx context.Context, productIds []int64) ([]ListVariantsOfProductsRow, error) {
	rows, err := q.db.Query(ctx, listVariantsOfProducts, productIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListVariantsOfProductsRow
	for rows.Next() {
		var i ListVariantsOfProductsRow
		if err := rows.Scan(
			&i.ID,
			&i.ProductID,
			&i.Sku,
			&i.Ean,
			&i.OptionValues,
			&i.PriceCents,
			&i.CompareAtCents,
			&i.SupplierSku,
			&i.SourceID,
			&i.CostCents,
			&i.RrpCents,
			&i.AvailabilityStatus,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const nextVariantNumber = `-- name: NextVariantNumber :one
SELECT nextval('variant_sku_seq')
`

func (q *Queries) NextVariantNumber(ctx context.Context) (int64, error) {
	row := q.db.QueryRow(ctx, nextVariantNumber)
	var nextval int64
	err := row.Scan(&nextval)
	return nextval, err
}

